package com.hbm.machine.gascentrifuge;
import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class GasCentrifugeContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");private static final DeferredRegister<RecipeType<?>> TYPES=DeferredRegister.create(Registries.RECIPE_TYPE,"hbm");private static final DeferredRegister<RecipeSerializer<?>> SERIALIZERS=DeferredRegister.create(Registries.RECIPE_SERIALIZER,"hbm");
 public static final DeferredBlock<GasCentrifugeBlock> BLOCK=BLOCKS.register("machine_gascent",GasCentrifugeBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem(BLOCK);public static final DeferredItem<GasCentrifugeUpgradeItem> SPEED=ITEMS.register("upgrade_gc_speed",GasCentrifugeUpgradeItem::new);public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<GasCentrifugeBlockEntity>> ENTITY=ENTITIES.register("gascentrifuge",()->BlockEntityType.Builder.of(GasCentrifugeBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<GasCentrifugePort>> PORT=ENTITIES.register("gascentrifuge_port",()->BlockEntityType.Builder.of(GasCentrifugePort::new,BLOCK.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<GasCentrifugeMenu>> MENU=MENUS.register("gascentrifuge",()->new MenuType<>((IContainerFactory<GasCentrifugeMenu>)GasCentrifugeMenu::new,FeatureFlags.DEFAULT_FLAGS));public static final DeferredHolder<RecipeType<?>,RecipeType<GasCentrifugeRecipe>> TYPE=TYPES.register("gascentrifuge",()->new RecipeType<GasCentrifugeRecipe>(){});public static final DeferredHolder<RecipeSerializer<?>,GasCentrifugeRecipe.Serializer> SERIALIZER=SERIALIZERS.register("gascentrifuge",GasCentrifugeRecipe.Serializer::new);
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);TYPES.register(bus);SERIALIZERS.register(bus);bus.addListener(GasCentrifugeContent::capabilities);}private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));}public static List<ItemStack> creativeStacks(String tab){return tab.equals("machine")?List.of(new ItemStack(ITEM.get())):tab.equals("control")?List.of(new ItemStack(SPEED.get())):List.of();}public static ResourceLocation id(String path){return ResourceLocation.fromNamespaceAndPath("hbm",path);}private GasCentrifugeContent(){}
}
